section.markdown:
Raoul a une position, des points de vie et une force. Avec ce qui a été vu jusqu'ici,
chaque valeur demande sa variable :

```js
let raoulX = 250;
let raoulVie = 20;
let raoulForce = 4;
```

Rien dans le code ne dit que ces trois variables vont ensemble : seul leur nom le
suggère. Billy en demande trois autres, `billyX`, `billyVie`, `billyForce`, et chaque
personnage ajouté en apporte trois de plus.

section.sketch:
let chevalier = {
  nom: "Raoul",
  x: 0
};

async function setup() {
  createCanvas(800, 600);
  await chargerPersonnages();
}

function draw() {
  background(20);
  dessinerChateau(650, 500, 260);
  dessinerRaoul(chevalier.x, 500, 60);
  chevalier.x = chevalier.x + 2;
}

let chevalier = {
  nom: "Raoul",
  x: 250,
  pointsDeVie: 20,
  force: 4
};

let ogre = {
  nom: "Billy",
  x: 600,
  pointsDeVie: 30,
  force: 3
};

async function setup() {
  createCanvas(800, 600);
  await chargerPersonnages();
}

function draw() {
  background(20);
  dessinerRaoul(chevalier.x, 500, 120);
  dessinerBilly(ogre.x, 500, 250);
  parler(chevalier.nom + " : " + chevalier.pointsDeVie, chevalier.x, 280);
  parler(ogre.nom + " : " + ogre.pointsDeVie, ogre.x - 40, 230);
}

function mousePressed() {
  if (chevalier.pointsDeVie > 0 && ogre.pointsDeVie > 0) {
    ogre.pointsDeVie = ogre.pointsDeVie - chevalier.force;
    chevalier.pointsDeVie = chevalier.pointsDeVie - ogre.force;
  }
}

let chevaliers = [];

async function setup() {
  createCanvas(800, 600);
  await chargerPersonnages();

  for (let i = 0; i < 3; i = i + 1) {
    chevaliers.push({ x: 0, y: 200 + i * 120, vitesse: lancerDe(4) });
  }
}

function draw() {
  background(20);
  stroke(240);
  line(700, 0, 700, 600);   // l'arrivée

  for (let i = 0; i < chevaliers.length; i = i + 1) {
    let c = chevaliers[i];
    dessinerRaoul(c.x, c.y, 50);
    if (c.x < 700) {
      c.x = c.x + c.vitesse;
    }
  }
}

function mousePressed() {
  chevaliers.push({ x: 0, y: mouseY, vitesse: lancerDe(4) });
}
